 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The uniform divider color separates panels; count foreground marks per panel.
    div = next((c for c in set(sum(grid, [])) if all(v == c for v in grid[2]) and c != grid[0][0]), None)
    if div is None:
        # Fall back to the most frequent full-width row.
        div = max(set(sum(grid, [])), key=lambda c: sum(all(v == c for v in row) for row in grid))
    rows = [r for r in range(h) if not all(v == div for v in grid[r])]
    cols = [c for c in range(w) if not all(grid[r][c] == div for r in range(h))]
    # panel spans are contiguous stretches between divider rows/columns
    rblocks=[]
    for r in rows:
        if not rblocks or r != rblocks[-1][-1]+1: rblocks.append([r])
        else: rblocks[-1].append(r)
    cblocks=[]
    for c in cols:
        if not cblocks or c != cblocks[-1][-1]+1: cblocks.append([c])
        else: cblocks[-1].append(c)
    bg=grid[0][0]
    mark=next((v for row in grid for v in row if v not in (bg, div)), bg)
    return [[1 if sum(grid[r][c] == mark for r in rb for c in cb) == 2 else bg for cb in cblocks] for rb in rblocks]
"
